import type {SaveResponseErrorDetails, WebCommitInfo} from '@github-ui/code-view-types'
import {FlashError} from '@github-ui/flash-error'
import {TextExpander} from '@github-ui/text-expander'
import {ScopedCommands} from '@github-ui/ui-commands'
import {GitPullRequestIcon, SyncIcon} from '@primer/octicons-react'
import {Button, Checkbox, CheckboxGroup, FormControl, Link, Radio, RadioGroup, Select, TextInput} from '@primer/react'
import {Dialog, type DialogProps} from '@primer/react/experimental'
import React, {useCallback, useEffect} from 'react'

import {BranchProtectionNotEnforcedBanner} from './BranchProtectionNotEnforcedBanner'
import {CommitButton} from './CommitButton'
import {FileStatusIcon} from './FileStatusIcon'
import styles from './WebCommitDialog.module.css'

const COMMIT_MESSAGE_INPUT_ID = 'commit-message-input'
const COMMIT_DESCRIPTION_INPUT_ID = 'commit-description-input'
const BRANCH_NAME_INPUT_ID = 'branch-name-input'

export type WebCommitDialogState = 'closed' | 'pending' | 'saving' | 'saved'

export type FileStatus = 'A' | 'D' | 'M' | 'R'
export type FileStatuses = {[key: string]: FileStatus}

export interface WebCommitDialogProps {
  additionalFooterContent?: React.ReactElement
  dialogProps?: Partial<DialogProps>
  helpUrl: string
  placeholderMessage?: string
  refName: string
  webCommitInfo: WebCommitInfo
  onSave: () => void
  dialogState: WebCommitDialogState
  setDialogState: (state: WebCommitDialogState) => void
  message: string
  setMessage: (message: string) => void
  description: string
  setDescription: (description: string) => void
  isQuickPull: boolean
  setAuthorEmail: React.Dispatch<React.SetStateAction<string | undefined>>
  setIsQuickPull?: React.Dispatch<React.SetStateAction<boolean>>
  prTargetBranch?: string
  setPRTargetBranch?: React.Dispatch<React.SetStateAction<string>>
  errorMessage?: string
  errorDetails?: SaveResponseErrorDetails
  fileStatuses?: FileStatuses
  selectedFiles?: Set<string>
  setSelectedFiles?: React.Dispatch<React.SetStateAction<Set<string>>>
  disableQuickPull?: boolean
  returnFocusRef?: React.RefObject<HTMLElement | null>
  directCommitDisabled?: boolean
  diffList?: React.ReactElement
  preventSubmit?: boolean
  preventSubmitMessage?: string
  isFetching?: boolean
  showGeneratingCommitMessageLoading?: boolean
  showGeneratingCommitMessageLoaded?: boolean
  hasShownGeneratedCommitMessage?: boolean
  onCopilotCommitGenerationCancel?: () => void
  onRegenerateCommitMessageClick?: () => void
}

// states and transitions:
// closed
//  -> pending
// pending
//  -> closed
//  -> saving
// saving
//  -> saved
//  -> pending
//  -> closed

export function WebCommitDialog({
  additionalFooterContent,
  disableQuickPull,
  dialogProps,
  helpUrl,
  placeholderMessage,
  refName,
  webCommitInfo,
  dialogState,
  onSave,
  setDialogState,
  fileStatuses,
  selectedFiles,
  setSelectedFiles,
  message,
  setMessage,
  description,
  setDescription,
  isQuickPull,
  setIsQuickPull,
  prTargetBranch,
  setPRTargetBranch,
  setAuthorEmail,
  errorMessage,
  errorDetails,
  returnFocusRef,
  directCommitDisabled,
  diffList,
  preventSubmit,
  preventSubmitMessage,
  showGeneratingCommitMessageLoading,
  showGeneratingCommitMessageLoaded,
  hasShownGeneratedCommitMessage,
  onCopilotCommitGenerationCancel,
  onRegenerateCommitMessageClick,
}: WebCommitDialogProps) {
  const {
    authorEmails,
    canCommitStatus,
    canCreatePullRequest,
    dcoSignoffEnabled,
    dcoSignoffHelpUrl,
    defaultEmail,
    defaultNewBranchName,
    forkedRepo,
    repoHeadEmpty,
    suggestionsUrlEmoji,
    suggestionsUrlIssue,
    suggestionsUrlMention,
  } = webCommitInfo

  const [branchNamedWrong, setBranchNamedWrong] = React.useState(false)
  const isSaving = dialogState === 'saving'
  const branchNameInputRef = React.useRef<HTMLInputElement>(null)
  const flashErrorRef = React.useRef<HTMLDivElement>(null)

  const handleChoiceOneChange = (selectedValue: string | null) => {
    setIsQuickPull?.(selectedValue === 'pr')
  }

  const commitMessageInputRef = React.useRef<HTMLInputElement>(null)
  useEffect(() => {
    if (commitMessageInputRef.current) {
      commitMessageInputRef.current.focus()
    }
  }, [])

  const isIMEOpen = React.useRef(false)

  let webCommitTitle = isQuickPull ? 'Propose changes' : 'Commit changes'

  if (dcoSignoffEnabled) {
    webCommitTitle = `Sign off and ${webCommitTitle.toLocaleLowerCase()}`
  }

  const quickPullChoice = !forkedRepo && !repoHeadEmpty && !disableQuickPull

  const saveHandler = async () => {
    if (isQuickPull && quickPullChoice && prTargetBranch === 'HEAD') {
      setBranchNamedWrong(true)
      branchNameInputRef.current?.focus()
      return
    }
    setBranchNamedWrong(false)
    onSave()
  }

  const checkboxHandler = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const path = event.target.value
      setSelectedFiles?.(prevSelectedFiles => {
        const newSelectedFiles = new Set(prevSelectedFiles)
        if (newSelectedFiles.has(path)) {
          newSelectedFiles.delete(path)
        } else {
          newSelectedFiles.add(path)
        }
        return newSelectedFiles
      })
    },
    [setSelectedFiles],
  )

  useEffect(() => {
    if (errorMessage && flashErrorRef.current) {
      flashErrorRef.current.focus()
    }
  }, [errorMessage])

  // remove nulls from author emails
  const filteredAuthorEmails = authorEmails.filter(email => email)

  // Use the danger button type if a user has to bypass rules to commit
  const saveButtonType = canCommitStatus !== 'allowed' && !isQuickPull ? 'danger' : 'primary'
  const saveButtonMessage =
    canCommitStatus === 'can_bypass' && !isQuickPull ? 'Bypass rules and commit changes' : webCommitTitle

  const submitCommandHandler = () => {
    if (preventSubmit || isSaving) return
    return saveHandler()
  }

  return (
    <ScopedCommands commands={{'github:submit-form': submitCommandHandler}}>
      <Dialog
        aria-labelledby="web-commit-dialog-header"
        onClose={gesture => {
          if (gesture !== 'close-button') {
            return
          }

          if (!isIMEOpen.current) {
            setDialogState('closed')
          }
        }}
        title={webCommitTitle}
        returnFocusRef={returnFocusRef}
        width="large"
        renderFooter={() => (
          <div className={styles.WebCommitDialogFooterActions}>
            {additionalFooterContent}
            <Button
              onClick={() => {
                setDialogState('closed')
              }}
            >
              Cancel
            </Button>
            <CommitButton
              preventSubmit={preventSubmit || false}
              preventSubmitMessage={preventSubmitMessage}
              isSaving={isSaving}
              saveHandler={saveHandler}
              saveButtonMessage={saveButtonMessage}
              saveButtonType={saveButtonType}
            />
          </div>
        )}
        className={styles.WebCommitDialogDialog}
        {...dialogProps}
      >
        <FlashError
          prefix="There was an error committing your changes:"
          errorMessageUsingPrefix={
            errorDetails?.ruleViolations ? 'Please address the rule violations and try again.' : errorMessage
          }
          ruleErrors={errorDetails?.ruleViolations}
          helpUrl={helpUrl}
          flashRef={flashErrorRef}
        />
        <form
          onSubmit={(event: React.FormEvent) => {
            saveHandler()
            event.preventDefault()
          }}
        >
          <FormControl id={COMMIT_MESSAGE_INPUT_ID}>
            <FormControl.Label className={styles.commitMessageLabel}>
              <span>Commit message</span>
            </FormControl.Label>
            <TextInput
              onChange={event => setMessage(event.target.value)}
              placeholder={showGeneratingCommitMessageLoading ? 'Copilot is thinking...' : placeholderMessage}
              value={message}
              ref={commitMessageInputRef}
              className={styles.commitMessageInput}
              // This uses onKeyDown because the input is in focus on load so the user starting to type is the signal of interaction
              onKeyDown={() => onCopilotCommitGenerationCancel?.()}
              aria-describedby={showGeneratingCommitMessageLoaded ? 'commit-message-generated' : undefined}
              trailingAction={
                showGeneratingCommitMessageLoaded ? (
                  <TextInput.Action
                    onClick={() => onRegenerateCommitMessageClick?.()}
                    icon={SyncIcon}
                    aria-label="Regenerate commit message"
                  />
                ) : undefined
              }
            />
            {/* Announce generated commit message to screen readers when it is generated */}
            {showGeneratingCommitMessageLoaded && (
              <div
                id="commit-message-generated"
                aria-live="polite"
                style={{
                  position: 'absolute',
                  width: '1px',
                  height: '1px',
                  padding: 0,
                  margin: '-1px',
                  overflow: 'hidden',
                  whiteSpace: 'nowrap',
                  border: 0,
                }}
              >
                Copilot commit message generated: {message}
              </div>
            )}
          </FormControl>

          <FormControl className={styles.commitDescription}>
            <FormControl.Label>Extended description</FormControl.Label>
            <TextExpander
              suggestionsUrlIssue={suggestionsUrlIssue}
              suggestionsUrlMention={suggestionsUrlMention}
              suggestionsUrlEmoji={suggestionsUrlEmoji}
              value={description}
              setValue={setDescription}
              textareaProps={{
                placeholder: showGeneratingCommitMessageLoading
                  ? 'Copilot is thinking...'
                  : 'Add an optional extended description...',
                onCompositionStart: () => (isIMEOpen.current = true),
                onCompositionEnd: () => (isIMEOpen.current = false),
                id: COMMIT_DESCRIPTION_INPUT_ID,
                // This uses onFocus because the user clicking into the input is the signal of interaction
                onFocus: () => onCopilotCommitGenerationCancel?.(),
              }}
              className={styles.commitDescriptionInput}
            />

            <FormControl.Caption>
              {hasShownGeneratedCommitMessage && (
                <div className={styles.generatingCommitMessageFeedback}>
                  <span className={styles.generatingCommitMessageFeedbackCopy}>
                    Message and description suggested by Copilot.
                  </span>
                </div>
              )}
            </FormControl.Caption>
          </FormControl>

          {filteredAuthorEmails.length > 1 ? (
            <FormControl className={styles.commitEmailFormControl}>
              {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
              <FormControl.Label>Commit Email</FormControl.Label>
              <Select
                onChange={ev => {
                  setAuthorEmail(ev.target.value)
                }}
                defaultValue={defaultEmail}
              >
                {authorEmails.map(email => (
                  <Select.Option key={email} value={email}>
                    {email}
                  </Select.Option>
                ))}
              </Select>
              {dcoSignoffEnabled && (
                <FormControl.Caption>
                  Choose an email address for{' '}
                  <Link href={dcoSignoffHelpUrl} target="_blank" rel="noreferrer" inline>
                    signing off
                  </Link>{' '}
                  on this commit
                </FormControl.Caption>
              )}
            </FormControl>
          ) : dcoSignoffEnabled ? (
            <div className={styles.commitEmailFormControl}>
              You are{' '}
              <Link href={dcoSignoffHelpUrl} target="_blank" rel="noreferrer" inline>
                signing off
              </Link>{' '}
              on this commit as {defaultEmail}
            </div>
          ) : null}
          {webCommitInfo.protectionNotEnforcedInfo?.upsellCtaInfo.visible && (
            <BranchProtectionNotEnforcedBanner
              branch={refName}
              protectionNotEnforcedInfo={webCommitInfo.protectionNotEnforcedInfo}
            />
          )}
          {quickPullChoice && (
            <RadioGroup name="pr-choice" onChange={handleChoiceOneChange}>
              <RadioGroup.Label visuallyHidden>Direct commit or PR</RadioGroup.Label>
              <FormControl>
                {canCommitStatus !== 'blocked' && !directCommitDisabled && (
                  <Radio
                    aria-checked={!isQuickPull}
                    aria-describedby={canCommitStatus === 'can_bypass' && !isQuickPull ? 'bypass-warning' : undefined}
                    value="direct"
                    defaultChecked={!isQuickPull}
                  />
                )}
                <FormControl.Label className={styles.commitOptionLabel}>
                  {directCommitDisabled ? (
                    <>Direct commits are disabled for closed pull requests.</>
                  ) : canCommitStatus !== 'blocked' ? (
                    <>
                      Commit directly to the <pre className={styles.branchNamePre}>{refName}</pre> branch
                    </>
                  ) : (
                    <>
                      You can’t commit to <pre className={styles.branchNamePre}>{refName}</pre> because it is a{' '}
                      <Link
                        href={`${helpUrl}/pull-requests/collaborating-with-pull-requests/proposing-changes-to-your-work-with-pull-requests/about-pull-requests`}
                        inline
                      >
                        protected branch
                      </Link>
                    </>
                  )}
                </FormControl.Label>
                {canCommitStatus !== 'blocked' && canCommitStatus === 'can_bypass' && !isQuickPull && (
                  <FormControl.Caption>Some rules will be bypassed by committing directly</FormControl.Caption>
                )}
              </FormControl>
              <FormControl>
                <Radio aria-checked={isQuickPull} value="pr" defaultChecked={isQuickPull} />
                <FormControl.Label className={styles.FormControl_Label}>
                  Create a <strong>new branch</strong> for this commit
                  {(canCreatePullRequest ?? true) ? ' and start a pull request' : ''}{' '}
                  <Link
                    href={`${helpUrl}/pull-requests/collaborating-with-pull-requests/proposing-changes-to-your-work-with-pull-requests/about-pull-requests`}
                    inline
                    className={styles.pullRequestHelpLink}
                  >
                    Learn more about pull requests
                  </Link>
                </FormControl.Label>
              </FormControl>
              {isQuickPull && (
                <div className={styles.quickPullBranchInputContainer}>
                  <FormControl id={BRANCH_NAME_INPUT_ID}>
                    {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
                    <FormControl.Label visuallyHidden>Branch Name</FormControl.Label>
                    <TextInput
                      ref={branchNameInputRef}
                      aria-label="PR target branch"
                      leadingVisual={GitPullRequestIcon}
                      onChange={event => setPRTargetBranch?.(event.target.value)}
                      placeholder={defaultNewBranchName}
                      value={prTargetBranch}
                      className={styles.branchNameInput}
                    />

                    {branchNamedWrong && (
                      <FormControl.Validation variant="error">
                        New branch name can not be &quot;HEAD&quot;
                      </FormControl.Validation>
                    )}
                  </FormControl>
                </div>
              )}
            </RadioGroup>
          )}
          {fileStatuses && selectedFiles && (
            <CheckboxGroup className={styles.fileCheckboxGroup}>
              <CheckboxGroup.Label>Changes to commit</CheckboxGroup.Label>
              {Object.entries(fileStatuses).map(([path, status]) => (
                <FormControl key={path}>
                  <Checkbox value={path} checked={selectedFiles.has(path)} onChange={checkboxHandler} />
                  <FormControl.Label className={styles.fileCheckboxLabel}>
                    <div className={styles.commitFileIcon}>
                      <FileStatusIcon status={status} />
                    </div>
                    {path}
                  </FormControl.Label>
                </FormControl>
              ))}
            </CheckboxGroup>
          )}
          {diffList}
        </form>
      </Dialog>
    </ScopedCommands>
  )
}
